import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv3d_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t padding, int64_t dilation, int64_t groups);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

__global__ void conv3d_forward_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    const int N, const int C, const int D, const int H, const int W,
    const int OC, const int OD, const int OH, const int OW,
    const int K, const int stride, const int pad, const int dilation,
    const int groups, const int has_bias)
{
    // Structural rewrite: cooperative shared-memory tiled path for the common
    // C==3, K==3, stride==1, dilation==1, groups==1 case. Each CTA computes a
    // 16x16 output tile for one (n, od, oc), staging the 3-channel input tile
    // (with halo) and the 81 weights in shared memory for full reuse.
    if (C == 3 && K == 3 && groups == 1 && stride == 1 && dilation == 1) {
        constexpr int TILE = 16;
        constexpr int HALO = 18;  // TILE + K - 1
        __shared__ float xs[3][3][HALO][HALO];
        __shared__ float ws[81];
        const int tiles_w = (OW + TILE - 1) / TILE;
        const int oh0 = (blockIdx.x / tiles_w) * TILE;
        const int ow0 = (blockIdx.x % tiles_w) * TILE;
        const int od = blockIdx.y;
        const int n  = blockIdx.z / OC;
        const int oc = blockIdx.z % OC;
        const int tid = threadIdx.x;
        if (tid < 81) ws[tid] = w[(long long)oc * 81 + tid];
        const int tile_elems = 3 * 3 * HALO * HALO;
        for (int i = tid; i < tile_elems; i += blockDim.x) {
            const int c  = i / (3 * HALO * HALO);
            int rem = i % (3 * HALO * HALO);
            const int kz = rem / (HALO * HALO);
            rem %= (HALO * HALO);
            const int hh = rem / HALO;
            const int ww = rem % HALO;
            const int id = od  - pad + kz;
            const int ih = oh0 - pad + hh;
            const int iw = ow0 - pad + ww;
            float v = 0.0f;
            if (id >= 0 && id < D && ih >= 0 && ih < H && iw >= 0 && iw < W)
                v = x[(((long long)n * C + c) * D + id) * H * W + (long long)ih * W + iw];
            xs[c][kz][hh][ww] = v;
        }
        __syncthreads();
        const int ty = tid / TILE;
        const int tx = tid % TILE;
        const int oh = oh0 + ty;
        const int ow = ow0 + tx;
        if (oh < OH && ow < OW) {
            float sum = has_bias ? b[oc] : 0.0f;
            #pragma unroll
            for (int c = 0; c < 3; ++c) {
                #pragma unroll
                for (int kz = 0; kz < 3; ++kz) {
                    #pragma unroll
                    for (int ky = 0; ky < 3; ++ky) {
                        #pragma unroll
                        for (int kx = 0; kx < 3; ++kx) {
                            sum += xs[c][kz][ty + ky][tx + kx] * ws[c * 27 + kz * 9 + ky * 3 + kx];
                        }
                    }
                }
            }
            y[(((long long)n * OC + oc) * OD + od) * OH * OW + (long long)oh * OW + ow] = sum;
        }
        return;
    }
    const long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long total = (long long)N * OC * OD * OH * OW;
    if (idx >= total) return;
    long long t = idx;
    const int ow = (int)(t % OW); t /= OW;
    const int oh = (int)(t % OH); t /= OH;
    const int od = (int)(t % OD); t /= OD;
    const int oc = (int)(t % OC); t /= OC;
    const int n  = (int)t;
    float sum = has_bias ? b[oc] : 0.0f;
    const int cpg = C / groups;
    const int ocpg = OC / groups;
    const int g = oc / ocpg;
    const int c_start = g * cpg;
    for (int c = 0; c < cpg; ++c) {
        const int ic = c_start + c;
        for (int kz = 0; kz < K; ++kz) {
            const int id = od * stride - pad + kz * dilation;
            if (id < 0 || id >= D) continue;
            for (int ky = 0; ky < K; ++ky) {
                const int ih = oh * stride - pad + ky * dilation;
                if (ih < 0 || ih >= H) continue;
                const long long x_base = ((((long long)n * C + ic) * D + id) * H + ih) * W;
                const long long w_base = ((((long long)oc * cpg + c) * K + kz) * K + ky) * K;
                for (int kx = 0; kx < K; ++kx) {
                    const int iw = ow * stride - pad + kx * dilation;
                    if (iw < 0 || iw >= W) continue;
                    sum += x[x_base + iw] * w[w_base + kx];
                }
            }
        }
    }
    y[idx] = sum;
}

torch::Tensor conv3d_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t padding, int64_t dilation, int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "input must be NCDHW");
    TORCH_CHECK(weight.dim() == 5, "weight must be [OC, C/groups, K, K, K]");
    TORCH_CHECK(groups > 0, "groups must be positive");

    const int64_t N = x.size(0), C = x.size(1), D = x.size(2), H = x.size(3), W = x.size(4);
    const int64_t OC = weight.size(0), CPG = weight.size(1), K = weight.size(2);
    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K, "kernel must be cubic");
    TORCH_CHECK(C % groups == 0 && OC % groups == 0, "invalid groups");
    TORCH_CHECK(CPG == C / groups, "weight/input channel mismatch");

    const bool has_bias = bias.defined() && bias.numel() == OC;
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "bias must be float32");
    }

    const int64_t OD = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int64_t OH = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int64_t OW = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    TORCH_CHECK(OD > 0 && OH > 0 && OW > 0, "invalid output size");

    auto y = torch::empty({N, OC, OD, OH, OW}, x.options());
    const long long total = (long long)N * OC * OD * OH * OW;
    if (total == 0) return y;

    const int threads = 256;
    const bool tiled = (C == 3 && K == 3 && groups == 1 && stride == 1 && dilation == 1);
    if (tiled && N * OC <= 65535 && OD <= 65535) {
        const int tiles_h = (int)((OH + 15) / 16);
        const int tiles_w = (int)((OW + 15) / 16);
        dim3 grid((unsigned)(tiles_h * tiles_w), (unsigned)OD, (unsigned)(N * OC));
        conv3d_forward_kernel<<<grid, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            has_bias ? bias.data_ptr<float>() : nullptr,
            y.data_ptr<float>(),
            (int)N, (int)C, (int)D, (int)H, (int)W,
            (int)OC, (int)OD, (int)OH, (int)OW,
            (int)K, (int)stride, (int)padding, (int)dilation,
            (int)groups, has_bias ? 1 : 0
        );
    } else {
        const long long blocks_ll = (total + threads - 1) / threads;
        TORCH_CHECK(blocks_ll <= 2147483647LL, "too many blocks");
        const int blocks = (int)blocks_ll;
        conv3d_forward_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            x.data_ptr<float>(),
            weight.data_ptr<float>(),
            has_bias ? bias.data_ptr<float>() : nullptr,
            y.data_ptr<float>(),
            (int)N, (int)C, (int)D, (int)H, (int)W,
            (int)OC, (int)OD, (int)OH, (int)OW,
            (int)K, (int)stride, (int)padding, (int)dilation,
            (int)groups, has_bias ? 1 : 0
        );
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
"""

_conv3d_ext = load_inline(
    name="custom_conv3d_direct_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv3d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if in_channels % groups != 0 or out_channels % groups != 0:
            raise ValueError("in_channels and out_channels must be divisible by groups")
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        k = self.kernel_size
        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels // self.groups, k, k, k))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda and self.weight.is_cuda:
            x = x.to(self.weight.device)
        x = x.contiguous()
        w = self.weight.contiguous()
        b = self.bias if self.bias is not None else torch.empty(0, device=w.device, dtype=w.dtype)
        return _conv3d_ext.conv3d_forward(x, w, b.contiguous(), self.stride, self.padding, self.dilation, self.groups)

